import React from 'react'
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from 'swiper/modules';
import Marquee from 'react-fast-marquee';
const HomePage = () => {
    return (
        <>
            {/* Baner */}

            <div className='h-[42vw] m-[3vw] rounded-lg overflow-hidden'
                style={{
                    boxShadow: "0 .53333vw 3.2vw #64656614"
                }}
            >
                <Swiper className="mySwiper" autoplay={{
                    delay: 2500,
                    disableOnInteraction: false,
                }}
                    modules={[Autoplay]}
                >
                    <SwiperSlide>Slide 1</SwiperSlide>
                    <SwiperSlide>Slide 2</SwiperSlide>
                    <SwiperSlide>Slide 3</SwiperSlide>
                </Swiper>
            </div>


            {/* Notice */}

            <div className='notice-bar'>
                <div className='van-notice-bar'>
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="size-14">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 0 1 0 12.728M16.463 8.288a5.25 5.25 0 0 1 0 7.424M6.75 8.25l4.72-4.72a.75.75 0 0 1 1.28.53v15.88a.75.75 0 0 1-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.009 9.009 0 0 1 2.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75Z" />
                    </svg>


                </div>
            </div>

        </>
    )
}

export default HomePage
